import json,subprocess,concurrent.futures,hashlib,io,urllib.parse
from pathlib import Path
from PIL import Image
B=Path(__file__).parent;R=json.loads((B/'kovo-receipt.json').read_text());C=json.loads((B/'kovo-clubs.json').read_text())['payload'];bycode={c['tcode']:c for c in C}
def get(u):return subprocess.run(['curl','-fsSL','--max-time','35','-A','Mozilla/5.0',u],capture_output=True,check=True).stdout
def verify(r):
 id=r['id'];m=json.loads(get('https://semologo.com/api/logo-variants/?id='+id+'&review=kovo20261027'));assert len(m['variants'])==r['total'];vs=[v for v in m['variants']if v['key'].startswith('official-kovo-20261027-')];v=next((v for v in vs if v['form']=='mascot'),vs[0]if vs else m['variants'][0]);u='https://logo.vibers.co.kr/_clients/'+id+'/'+(v.get('preview_png')or v['files']['png']);raw=get(u);Image.open(io.BytesIO(raw)).verify();name=bycode[r['tcode']]['name'];cat=json.loads(get('https://semologo.com/api/catalog/?q='+urllib.parse.quote(name)));visible=any(x['id']==id for x in cat['brands']);return {'id':id,'name':name,'added':r['added'],'merged_exact_duplicates':r['merged_exact_duplicates'],'total':r['total'],'variant_api_verified':True,'png_verified':True,'public_catalog_visible_for_exact_name':visible,'sample':u,'sample_sha256':hashlib.sha256(raw).hexdigest(),'representative_preserved':r['representative_preserved'],'hidden_state_preserved':r['hidden_state_preserved']}
a=list(concurrent.futures.ThreadPoolExecutor(max_workers=4).map(verify,R));assert len(a)==14;(B/'kovo-public-verification.json').write_text(json.dumps(a,ensure_ascii=False,indent=2));print(json.dumps(a,ensure_ascii=False,indent=2));print('added',sum(x['added']for x in a),'merged',sum(x['merged_exact_duplicates']for x in a),'visible',sum(x['public_catalog_visible_for_exact_name']for x in a))
